mapper.select:
select item_review_id as itemReviewId, user_id as userId, item_id as itemId, item_review_comment as itemReviewComment, item_rating as itemRating, item_time as itemTime
from item_review
where item_id = #{itemId}
order by item_time desc;

select item_review_id as itemReviewId, user_id as userId, item_id as itemId, item_review_comment as itemReviewComment, item_rating as itemRating, item_time as itemTime
from item_review
where item_review_id = #{itemReviewId};

mapper.update:
update item_review
set item_review_comment = #{itemReviewComment},
    item_rating = #{itemRating}
where item_review_id = #{itemReviewId};
